fn reverse_upto_k(s: &mut Vec<i32>, k: usize) {
    let len = s.len();
    // Reverse the first k elements
    for i in 0..k / 2 {
        s.swap(i, k - 1 - i);
    }
}

fn main() {
    let mut arr = vec![1, 2, 3, 4, 5];
    let k = 3;
    reverse_upto_k(&mut arr, k);
    println!("{:?}", arr); // Output should be [3, 2, 1, 4, 5]
}